# Correlated-Factors Group CFA. Options, results and panel:
# jamovi/groupCfaCorr.*.yaml (generated by tools/gen_yaml.py); jmvtools
# generates R/groupCfaCorr.h.R. All of the work is shared with groupCfaOne:
# see R/jmv-invariance.R.

groupCfaCorrClass <- if (requireNamespace("jmvcore", quietly = TRUE)) R6::R6Class(
  "groupCfaCorrClass",
  inherit = groupCfaCorrBase,
  private = list(
    .factors = function() psw_jmv_factors(self$options$factors),
    .init = function() psw_jmv_inv_init(self, private$.factors()),
    .run = function() psw_jmv_inv_run(self, private$.factors()),
    .diagram = function(image, ...) psw_jmv_diagram(image)
  )
)
